GimCorpus.put(416,0,[[1,2,"בלחי העליון. כתב הראב\"ד ז\"ל זה אינו צודק והוא שקר שהרי יש שפן וארנבת. עכ\"ל:",1,0],[1,2,"היא מפרסת פרסה. כתב הראב\"ד ז\"ל אף זה שקר מפורש בתורה. עכ\"ל:",2,0],[1,4,"כמין בהמה טמאה וכו'. כתב הראב\"ד ז\"ל והוא שיהיה הטמא בעדרו. עכ\"ל:",1,0],[1,10,"וסימני חיה מפי השמועה וכו'. כתב הראב\"ד ז\"ל זה הלשון כמה הוא משובש והיה ראוי לומר אם אינן מפוצלות אם היו קרניו כרוכות אף על פי שדומים לקרני השור וחרוקות אף על פי שדומות לקרני העז אם יהיה החרק מובלע בהן והדורות כקרני הצבי הרי זו חיה טהורה כשיהיו בקרנים סימנים הללו כרוכות חרוקות והדורות לפי שאין לך חיה שאין לה שלשה סימנים הללו. עכ\"ל:",1,0],[1,12,"והקרש וכו'. כתב הראב\"ד ז\"ל ולמה כתב בקרש ספק ובגמרא אסיק דמין חיה הוא עכ\"ל:",1,0],[2,17,"אבל דג מליח וכו'. כתב הראב\"ד ז\"ל שבוש הוא זה שאף בשר מליח תולעתו מותרת אבל מה שאמרו מורנא דבשרא אסירי דכוורי שריין תולעים שהיו בו מחיים קאמר ודכוורי שרי דחיי הדגים כמיתתן דמו עכ\"ל:",1,0],[2,23,"לוקה חמש וכו'. כתב הראב\"ד ז\"ל המאסף הזה אסף דברים שאינם בעולם שלא שמענו מימינו נמלה גדלה במים ולא שרץ העוף גדל במים. ואם בשביל ששולין דגים ואוכלין טעות הוא בידו ואילו מצאו חכמים מין זה לא היו משנים מפוטיתא לנמלה ומנמלה לצרעה. עכ\"ל:",1,0],[3,4,"מכת מרדות. כתב הראב\"ד ז\"ל הא למדת שאין בבשר האדם אפילו איסור עשה. ומה שאמר כיונק שקץ (לפי שאינו עומד לאכילה שאינו בר שחיטה לפיכך לא אמרו שהוא יונק שקץ אלא כיונק שקץ) בין תבין עכ\"ל:",1,0],[3,11,"אפרוח שנולד וכו'. כתב הראב\"ד ז\"ל מה ראה לשנות הטעמים שפירשו בו חכמים שהם מתוקנין יותר מכולם כי ביצת טרפה אינה ממין טמא ואסורה והטעם שפירשו בו לאימת קא גביל לכי קא מסרחא וכי מסרח עפרא בעלמא הוא. עכ\"ל:",1,0],[3,18,"אינו סומך עליו. כתב הראב\"ד ז\"ל דבריו אינם אלא בישראל שאינו מוחזק בנאמנות אבל מוחזק בנאמנות שאינו מכניס עצמו על הספק לוקחין ממנו בסתם. עכ\"ל:",1,0],[3,22,"צירן אסור וכו'. כתב הראב\"ד ז\"ל ציר חגבים טהור בירושלמי שאינו מכשיר. עכ\"ל:",1,0],[4,17,"כל הנבלות וכו'. כתב הראב\"ד ז\"ל פלוגתא היא במעילה ורב ורב אסי הוא דאמרי הכי ולוי פליג עלייהו וברייתא מסייעא ללוי דמצטרפי. עכ\"ל:",1,0],[4,20,"עור הבא כנגד פניו. כתב הראב\"ד ז\"ל רב ששת פשט להו לאיסורא במסכת בכורות ממתני'. עכ\"ל:",1,0],[5,2,"בשר גידים ועצמות וכו'. כתב הראב\"ד ז\"ל תימא הוא זה ומאי שנא זה מן הבשר החי שאין בו אלא משום טריפה. עכ\"ל:",1,0],[5,3,"ואין העצמות וכו'. כתב הראב\"ד ז\"ל ולמה ליה למכתב הכי ואפילו חלקו לאבר כמות שהוא לשנים מבחוץ פטור אם אין עליו כזית בשר. עכ\"ל:",1,0],[5,11,"האוכלו אינו לוקה. כתב הראב\"ד ז\"ל זה שבוש שהרי אמר למעלה אפילו החזירה וחתכה אחר שחיטה לוקה משום ובשר בשדה טרפה ובמשנה אמרו שחט את אמו ואח\"כ חתכו חכמים אומרים מגע טריפה שחוטה אלמא אית ביה איסור טריפה והל\"ל אינו לוקה משום אבר מן החי דאין שחיטה עושה ניפול ועם כל זה מה צורך הואיל ויש בו לאו דטריפה. עכ\"ל:",1,0],[5,13,"ומצא בה שליל וכו'. כתב הראב\"ד ז\"ל מכדי קי\"ל דשליא אינו אוכל דפרשא בעלמא היא וכי יש עמה ולד קשור דליכא בה חשש ולד נימוח אמאי אסורה לא כולה ולא מקצתה. עכ\"ל:",1,0],[6,1,"דגים וחגבים וכו'. כתב הראב\"ד ז\"ל אלא שאסרוהו במכונס מפני מראית העין אא\"כ יש בו קשקשים עכ\"ל:",1,0],[6,6,"הלב בין לצלי וכו'. כתב הראב\"ד ז\"ל לא נאמר אלא בצלי דכבולעו כך פולטו. עכ\"ל:",1,0],[6,10,"כדי שיתלבן וכו'. כתב הראב\"ד ז\"ל (זה) לא שמענו ולא ראינו מימינו וכל האדמימות שיצא אחר מליחה ממנו אינו אלא חמר בשר והמחמיר יותר מכן עליו להביא ראיה עכ\"ל:",1,0],[6,12,"והרוצה לאכול בשר חי וכו'. כתב הראב\"ד ז\"ל לבשר חי אינו צריך מליחה דדם האברים דלא פירש מותר וכן כתב רב אחאי ז\"ל. עכ\"ל:",1,0],[6,17,"עופות שהניחם שלמים וכו'. כתב הראב\"ד ז\"ל זה אין לו טעם אם הוא מלוח כל צרכו והבשר שבתוכו צלוי איזה דם יאסור אותו. עכ\"ל:",1,0],[7,3,"ומצא בה שליל וכו'. כתב הראב\"ד ז\"ל אין זה כדברי הרב ז\"ל אלא כדברי הרב רבינו אפרים ז\"ל. עכ\"ל:",1,0],[7,9,"ויש מן הגאונים וכו'. כתב הראב\"ד ז\"ל וזה עיקר. עכ\"ל:",1,0],[9,10,"לתוך המרק וכו'. כתב הראב\"ד ז\"ל אנו אומרים שלא שמענו כל החתיכה נעשית נבלה אלא לדעת ר' יהודה דמחמיר מין במינו אבל לרבנן לא ולדברי הכל אם לא ניער כלל אין שאר החתיכות נאסרות ומתניתין הכי משמע טיפת חלב שנפלה ע\"ג חתיכה ויש בה בנ\"ט באותה חתיכה אסור ניער את הקדרה אם יש בנ\"ט בכל הקדרה כל הקדרה אסורה למה לי ניער את הקדרה והלא החתיכה קבלה טעם חלב ונעשית נבלה בלא ניעור הרי יוצאת מאותה חתיכה רוטב לשאר חתיכות והוא רוטב נבילה אלא ש\"מ דבעינן שיצא מן החלב האסור לחתיכות והוא חלב נבילה שקיבל טעם הבשר ואם יש באותו חלב כדי ליתן טעם בכל החתיכות אסורות לרבנן ולר\"י נמי אע\"ג דאמר חתיכה עצמה נעשית נבלה הא אמרינן בגמרא נראין דברי ר\"י בשלא ניער והוינן בה מאי לא ניער אי לימא לא ניער כלל מיבלע בלע ולא פליט אלמא אע\"ג דאמרינן חתיכה עצמה נעשית נבלה ואוסרת כל שאר החתיכות במשהו לא אמרו אלא בשניער והוא תימה שהרי יוצא מן החתיכה רוטב בלא שום ניעור ואם היא נבלה מה צורך לניעור שיצא משם חלב. עכ\"ל:",1,0],[9,16,"ומפני חשש זה אסרו גבינת עכו\"ם כמו שביארנו. א\"א דברי רבינו אבן מגש ז\"ל הם אבל אנו אין צריכין לכך שאין הקושיא צריכה תירוץ:",1,0],[9,18,"ואם נאכל כמות שהוא כמו הכותח אינו כרותח. א\"א לא כיון יפה שלא נאמר בגמרא נאכל מחמת מלחו על הכותח אלא בר יונה שנפל לתוך הכותח ואף לא ירד לפרש אינו נאכל מחמת מלחו. וכך אנו מפרשים הבשר מליח כל כך שאינו נאכל בעינו מחמת מלחו אלא עם לפתן והרי לפירושו אין כותח נאכל בעינו כדאיתא בפסחים:",1,0],[9,25,"אבל מניח כד החומץ בצד כד הכמך. א\"א גירסא אחרת יש אצלנו:",1,0],[10,5,"תבואה שהשרישה אחר העומר. א\"א זה שיבוש ומי יתירם לאלו אלא שהשרישו קודם לעומר וחזר וזרע היתה השאלה אם התירן העומר שעבר אם לאו. עכ\"ל:",1,0],[10,14,"נכרי וישראל שהיו שותפין וכו'. א\"א אנו מפרשים באותו מעשה שלא היו צריכין להתנות בתחלה לפי שאין בשני ערלה אכילת איסור אלא שזמר העצים וזרע תחתיהן ירק ואכל שהיו האילנות קטנים והיה השדה ראוי לזרוע שם ולפיכך ישראל שאכל אחריו שני היתרא לא אכל דמי איסורא:",1,0],[10,17,"ואומר הרי כל הפירות וכו'. א\"א זהו תימה דהא ילפינן קדש קדש ממעשר שני ומה להלן כסף אף כאן כסף:",1,0],[10,20,"ואפילו לא נשאר בו אלא מעשר עני וכו' עד ואין בו מיתה. א\"א סברא היא זו והיא יפה בעיני משום דכתיב בהנך קראי קדש:",1,0],[11,18,"וכן כוס של חרס וכו'. א\"א אין זאת הגירסא אצלנו ולא בהלכות הרב ז\"ל אלא על השתיה ולא על ההדחה. ומה שאמר בסוף אבל של חרס צריך הדחה שבוש גדול הוא זה אטו מעיקרא לא בהדחה קאמר. עכ\"ל:",1,0],[11,21,"גת של אבן מזופפת וכו' ואם ישנה י\"ב חדש וכו'. א\"א אומר אני לשלשה ימים צריך קליפה לפי שאין המים נכנסין שם אלא לאחר כמה ונמצאו לשלשה ימים חוזרין ויש אומר אף לשנים עשר חדש מידי דהוה אקיטרי דאמרינן אי אית בהו קיטרי שרי להו:",1,0],[11,22,"גת של חרס אע\"פ שקלף את הזפת אסור לדרוך בה מיד עד שירפה את הזפת. א\"א זה שבוש אלא עד שיכניס בו גחלים ויתלבן כדי שיתרפה הזפת אם היה שם:",1,0],[11,25,"וכן הבשר והגבינה וכו'. א\"א זו אינה משנה שאין עמי הארץ חשודים להחליף ולא למכור דבר האסור אא\"כ נחשד:",1,0],[12,1,"כיצד יהיה הנגיעה וכו' אבל אם פשט ידו לחבית ותפשו את ידו. א\"א זה המחבר לא בא לפרש אלא לסתום וכשפשט ידו לחבית ותפשו את ידו מי לא נגע ביין אלא כך אמרו תפשו את ידו שלא ישכשך שאינו אוסר בהנאה אלא אם כן ישכשך:",1,0],[12,1,"אע\"פ שלא הגביה הכלי ולא נגע ביין נאסר היין. א\"א והוא שנתז מן היין:",2,0],[12,7,"נכנס העכו\"ם לבית וכו'. א\"א זה המעשה של עכו\"ם שנכנס לחנות ואמר איכא חמרא לזבוני וכו' ושדא ידיה לכובא ושכשך ביה ואמר האי לאו חמרא הוא ואסרוהו בהנאה מפני השכשוך:",1,0],[12,9,"או שנטל חבית וזרקה בחמתו לבור. א\"א זה שבוש שהרי אם זרקה בחמתו אפילו אזיל מיניה מותר בשתיה ואם זרקה ממש אפילו שלא בחמתו מותר בשתיה מיד:",1,0],[12,10,"ושתחת הנקב וכו'. א\"א אין בעלי הוראה מודין לו שיהא מותר בשתייה לא יהא אלא מערב ותניא בתוספתא דדמאי קרא שם לשולי חבית לא ישתה מפיה לפיה לא ישתה משוליה מפני שהמשקים מעורבים:",1,0],[12,12,"המערה יין לתוך כלי שיש בו יין עכו\"ם נאסר כל היין שבכלי. א\"א אני אומר בשתיה:",1,0],[12,14,"ויאסור כל מה שישאר בו שהרי בא היין מכחו. א\"א אני אומר והוא שהתחיל למשוך:",1,0],[12,23,"ותינוק הנמצא בין החביות וכו'. א\"א זה כתב בשביל שראה ההיא רביתא דאשתכחא ביני דני והוה נקיטא אופיא בידה נדמה לו אף על פי שלא היתה נתפסת כגנב התירו את היין מפני שהיתה תינוקת. ולא היא נתפסת כגנב היתה ואף על פי שהיתה אופיא בידה התירוהו:",1,0],[13,2,"ואם אמר לו אחוז לי מפתח זה עד שאביא היין מותר. א\"א זה שבוש שלא אמרו כך אלא כשהיין והבית של ישראל אבל כשהבית של עכו\"ם וישראל דר בחצר אחרת אפי' לא הפקיד לו את המפתח אלא שהניחה בדלת היין אסור משום שיש לו שייכות בבית:",1,0],[13,3,"דר באותה חצר וכו'. א\"א זה שבוש שאין הבית צריך לכך:",1,0],[13,3,"ואף על פי שהמפתח והחותם ביד ישראל. א\"א עד שיהיה שם שומר נכנס ויוצא:",2,0],[13,9,"והוא שייחד לו קרן זוית. א\"א זה שבוש אלא או שייחד לו קרן זוית והמפתח בידו:",1,0],[13,18,"ונמצא אחת מהן יין שכרו כולו אסור. א\"א ומאחר דקי\"ל כר' אליעזר דאמר יין ביין בסתם יינם יוליך הנאה לים המלח והשאר מותר בהנאה אמאי כולן אסורות א\"ו יוליך אחד מהם לים המלח והשאר מותר עכ\"ל:",1,0],[13,24,"ואם מדד ולא לקח דמים וכו'. א\"א הא נמי דלאו כהלכתא שהלכה כרבי אליעזר וכרשב\"ג:",1,0],[13,27,"מלך שהיה מחלק יינו לעם. א\"א דבריו מבולבלים וסתומים אלא מלך שיש לו מס על העם לתת לו יין כל אחד לפי מה שהוא ויש על זה הישראל בור אחד יין ששוה מאה דינרים ופרעהו לעכו\"ם לא יאמר אליו טול מאה דינרים ועול תחתי לאוצר המלך שהוא כאילו אמר לו קנה לי בור יין ופרעהו למלך בשבילי אבל אמר לו מלטני מן האוצר דמשמע סלקני במעות האלו כלומר קבל אתה עליך חוב המלך ויהיו אלו המעות שלך:",1,0],[14,6,"יראה לי שכל החייב בתרומה ובמעשרות וכו'. א\"א בעינן טעמן שוה כדאמרינן בעלמא ג' שמות והם מין אחד שלשה מינין והם שם אחד אסור ומצטרפין ובירושלמי ניחא ג' שמות והן מין אחד שלשה מינין והם שם אחד אמר חזקיה במיני מתיקה אלמא אפילו באיסור אחד דהיינו שם אחד בעינן טעם אחד והני שבעה מיני טבל לאו חד טעמא נינהו:",1,0],[15,8,"אלא חייב לאכול התערובת וכו'. א\"א ויש ביעור אחר בפירות שביעית שהוא לשריפה או לקבורה והוא שיכלה המין האחרון שבאותה הארץ משלש ארצות החלוקות לביעור ואותו זמן בין במינו בין שלא במינו בנותן טעם:",1,0],[15,12,"יראה לי שאפילו דבר שיש לו מתירין וכו'. א\"א משנה שלימה היא:",1,0],[15,14,"נפלה לפחות ממאתים הכל אסור בהנייה. א\"א אינו כן שאין לך דבר שאוסר עירובו בהנאה אלא אם כן הוא דבר שבמנין חוץ מאיסורי עכו\"ם ויי\"נ דוק ותשכח:",1,0],[15,18,"וכחל מן המנין הואיל והכחל מדבריהם. א\"א ויש נותן טעם טוב מזה מפני שהוא היתר כשהוא בעצמו:",1,0],[16,7,"או פטר חמור באלף חמורים כולן אסורין בהנייה. א\"א כיון דקי\"ל כר' אליעזר וכר' שמעון בן גמליאל יוליך הנאה לים המלח והשאר מותר בהנאה שהרי הלך חשיבותו:",1,0],[16,15,"אע\"פ שכל אחד מהם וכו'. א\"א זה אינו כלום שהרי כל אלה שם אחד הוא שהרי חמירא דחיטי וחמירא דשערי וחלא דחמרא וחלא דשכרא חד שמא חשיב להו בע\"ז ועוד השמות הללו איסורין הן:",1,0],[16,19,"שכיון שבטל האיסור שנפל תחלה נעשה הכל כחולין המותרין. א\"א כמה אוהב זה המחבר חשבונות גדולות עד שהניח חשבון המשנה שלשה קבין ערלה שנפלו למאה סאה של חולין ואח\"כ נפלו שם סאה ועוד של תרומה הרי הערלה מעלה את התרומה פי' שאותו ועוד אחד באותן שלשה קבין של ערלה שנפלו שם והם עצמם מבטלין אותן:",1,0],[16,28,"אבל אם עירה יין נסך מצלצול קטן לתוך וכו'. א\"א הא דלא כהלכתא ממתניתא דאגרדמין:",1,0],[16,34,"ולמה אין בודקין החטים וכו'. א\"א משום דאית בהו ציריא כמבוקעות דמיין:",1,0]]);
